mapper.select:
SELECT DISTINCT rp.merchant_id
  FROM reservation_products rp
  JOIN merchants m ON m.id = rp.merchant_id
  JOIN product_daily_inventories pdi ON pdi.product_id = rp.id
 WHERE m.region_id = #{regionId}
   AND m.category = #{merchantCategory}

     AND rp.product_detail_type = #{productDetailType}

   AND pdi.inventory_date >= #{startDate}

     AND pdi.inventory_date <= #{endDate}


     AND pdi.inventory_date < #{endDate}

   AND pdi.is_available = 1
   AND pdi.remaining_capacity > 0

 GROUP BY rp.id
 HAVING COUNT(DISTINCT pdi.inventory_date) = #{requiredInventoryDateCount}
    AND MIN(CASE WHEN pdi.is_available = 1 AND pdi.remaining_capacity > 0 THEN 1 ELSE 0 END) = 1
